create table if not exists public.route_discovery_sessions (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, route_id uuid references public.route_plans(id) on delete cascade, origin_lat double precision, origin_lng double precision, destination_lat double precision, destination_lng double precision, corridor_meters integer not null default 1000, route_geometry jsonb, status text not null default 'planned' check (status in ('planned','discovering','ready','active','completed','failed')), discovered_at timestamptz, expires_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index if not exists route_discovery_sessions_user_idx on public.route_discovery_sessions(user_id,created_at desc); create index if not exists route_discovery_sessions_route_idx on public.route_discovery_sessions(route_id); create table if not exists public.route_discovery_locations (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.route_discovery_sessions(id) on delete cascade, location_id uuid not null references public.locations(id) on delete cascade, trigger_radius_meters integer not null default 300, distance_along_route_meters double precision, source text not null default 'supabase_cache', discovered_at timestamptz not null default now(), geofence_enabled boolean not null default true, unique(session_id,location_id)); create index if not exists route_discovery_locations_session_idx on public.route_discovery_locations(session_id,geofence_enabled); create table if not exists public.route_discovery_cells (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.route_discovery_sessions(id) on delete cascade, cell_key text not null, source text not null default 'supabase_cache', refreshed_at timestamptz not null default now(), unique(session_id,cell_key)); alter table public.route_discovery_sessions enable row level security; alter table public.route_discovery_locations enable row level security; alter table public.route_discovery_cells enable row level security; drop policy if exists route_discovery_sessions_owner on public.route_discovery_sessions; create policy route_discovery_sessions_owner on public.route_discovery_sessions for all using (auth.uid()=user_id) with check (auth.uid()=user_id); drop policy if exists route_discovery_locations_owner on public.route_discovery_locations; create policy route_discovery_locations_owner on public.route_discovery_locations for all using (exists(select 1 from public.route_discovery_sessions s where s.id=session_id and s.user_id=auth.uid())) with check (exists(select 1 from public.route_discovery_sessions s where s.id=session_id and s.user_id=auth.uid())); drop policy if exists route_discovery_cells_owner on public.route_discovery_cells; create policy route_discovery_cells_owner on public.route_discovery_cells for all using (exists(select 1 from public.route_discovery_sessions s where s.id=session_id and s.user_id=auth.uid())) with check (exists(select 1 from public.route_discovery_sessions s where s.id=session_id and s.user_id=auth.uid())); create or replace function public.prepare_route_discovery(p_route_id uuid,p_corridor_meters integer default 1000,p_expires_minutes integer default 180) returns public.route_discovery_sessions language plpgsql security invoker set search_path=public as $$ declare v_user uuid:=auth.uid(); v_route public.route_plans; v_session public.route_discovery_sessions; begin if v_user is null then raise exception 'Authentication required'; end if; select * into v_route from public.route_plans where id=p_route_id and user_id=v_user; if not found then raise exception 'Route not found'; end if; insert into public.route_discovery_sessions(user_id,route_id,origin_lat,origin_lng,destination_lat,destination_lng,corridor_meters,status,expires_at) values(v_user,p_route_id,v_route.start_lat,v_route.start_lng,v_route.end_lat,v_route.end_lng,greatest(100,p_corridor_meters),'planned',now()+make_interval(mins=>greatest(15,p_expires_minutes))) returning * into v_session; return v_session; end $$; grant execute on function public.prepare_route_discovery(uuid,integer,integer) to authenticated;
